function saved(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}}
const state={page:'market',market:'全部市场',query:'',selected:'csi300',range:'近 6 月',watch:saved('ah-watch-v1',['csi300','hstech','sp500']),account:saved('ah-account-v1',initial),dialog:null,trade:'buy',messages:[],busy:false,backtest:null,config:{url:'https://api.openai.com/v1',model:'gpt-4.1-mini',key:''}};
const $=s=>document.querySelector(s),fmt=(n,d=2)=>Number(n).toLocaleString('zh-CN',{minimumFractionDigits:d,maximumFractionDigits:d}),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function persist(){localStorage.setItem('ah-watch-v1',JSON.stringify(state.watch));localStorage.setItem('ah-account-v1',JSON.stringify(state.account))}
function toast(t){$('#toast').textContent=t;$('#toast').className='visible';setTimeout(()=>$('#toast').className='',2800)}
function spark(seed=0,width=200,height=60,up=true){let pts=Array.from({length:60},(_,i)=>[i*width/59,height*.68-i*height/110+Math.sin(i*1.8+seed)*height*.08+Math.cos(i*.45+seed)*height*.18]);if(!up)pts=pts.map(([x,y])=>[x,height-y]);return pts.map(p=>p.join(',')).join(' ')}
function chart(seed=0,compare=false){const selected=indices.find(x=>x.id===state.selected), r=state.backtest;let pts=spark(seed,800,210,compare||selected.change>=0);let axis=compare?[1.3,1.2,1.1,1]:[1.07,1.02,.97,.92].map(v=>v*selected.value);let dates=compare&&r?Array.from({length:5},(_,n)=>new Date(new Date(r.start).getTime()+(new Date(r.end)-new Date(r.start))*n/4).toISOString().slice(0,10)):null;return `<div class="chart"><div class="chart-y">${axis.map(v=>`<span>${fmt(v,compare?2:0)}</span>`).join('')}</div><svg viewBox="0 0 800 245" role="img" aria-label="${compare?'模拟策略与基准净值曲线':'所选指数的合成历史走势'}"><defs><linearGradient id="fade" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#27a37c" stop-opacity=".17"/><stop offset="1" stop-color="#27a37c" stop-opacity="0"/></linearGradient></defs>${[30,85,140,195].map(y=>`<line x1="0" x2="800" y1="${y}" y2="${y}" stroke="#e9eeeb" stroke-dasharray="4 5"/>`).join('')}<polygon points="0,240 ${pts} 800,240" fill="url(#fade)"/>${compare?`<polyline points="${spark(seed+2,800,240)}" fill="none" stroke="#9eaaba" stroke-width="2" stroke-dasharray="6 5"/>`:''}<polyline points="${pts}" fill="none" stroke="#168567" stroke-width="2.8" stroke-linejoin="round"/></svg><div class="chart-x">${(dates||(state.range==='近 1 月'?['08/11','08/18','08/25','09/01','09/10']:state.range==='近 1 年'?['2025/09','2025/12','2026/03','2026/06','2026/09']:['03/11','04/20','05/29','07/08','09/10'])).map(d=>`<span>${d}</span>`).join('')}</div></div>`}
function signalClass(i){return i.signal.includes('入场')?'good':i.signal.includes('离场')?'bad':'neutral'}
const nav=[['market','◫','行情总览'],['watch','☆','我的自选'],['portfolio','▤','模拟持仓'],['agent','✧','Agent 助手'],['strategies','⊞','策略管理'],['backtest','⌁','策略回测']];
function render(){let i=indices.find(x=>x.id===state.selected);$('#app').innerHTML=`<aside><a class="brand" href="#" data-page="market"><b>α</b><span>ALPHA<br><strong>HUNTER</strong></span></a><div class="nav-label">投资工作台</div><nav>${nav.map(([id,icon,label])=>`<button class="${state.page===id?'active':''}" data-page="${id}"><span>${icon}</span>${label}${id==='agent'?'<small>BETA</small>':''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="demo-chip">本地演示空间</div><p>从数据到决策<br>让每一步都有依据。</p><button class="profile" data-action="settings"><span class="avatar">AH</span><span>个人投资账户<small>模型与 API 设置 ⚙</small></span></button></div></aside><main><header><div class="breadcrumb">工作台 <span>/</span> ${nav.find(n=>n[0]===state.page)[2]}</div><div class="header-right">${Research.orb()}<span class="demo-label">DEMO · 合成数据</span><span class="date">2026 年 9 月 11 日</span><button class="icon-btn" aria-label="模型设置" data-action="settings">⚙</button></div></header><div class="content">${state.page==='market'?marketView(i):state.page==='watch'?watchView():state.page==='portfolio'?portfolioView():state.page==='agent'?agentView():state.page==='strategies'?Research.strategyPage():backtestView()}</div><footer>Alpha Hunter · 交互原型 <span>所有行情、信号及回测均为演示，不构成投资建议 · 买卖仅本地模拟记账</span></footer></main><div id="agent-drawer-root"></div>${state.dialog?dialogView():''}`;bind();if(state.page==='market')MarketChart.bind(i);Research.afterRender()}
function title(k,t,sub,extra=''){return `<div class="page-title"><div><div class="eyebrow">${k}</div><h1>${t}</h1><p>${sub}</p></div>${extra}</div>`}
function marketView(i){const list=indices.filter(x=>(state.market==='全部市场'||(state.market==='红利专题'?x.category==='红利':x.market===state.market))&&(`${x.name}${x.code}${x.category||''}${x.aliases||''}`.toLowerCase().includes(state.query.toLowerCase())));return `${title('MARKET OVERVIEW','发现市场的下一步','横跨 A 股、港股与美股，追踪指数与策略机会。','<button class="btn" data-page="watch">查看我的自选 ↗</button>')}<div class="summary-grid">${['csi300','hsi','sp500'].map(id=>{const n=indices.find(i=>i.id===id);return `<button class="summary-card ${n.id===i.id?'selected':''}" data-index="${n.id}"><div class="row"><span>${n.name}</span><small>${n.market} · 指数</small></div><div class="summary-price">${fmt(n.value)}</div><div class="row"><span class="up">+${n.change.toFixed(2)}% <small>演示日涨幅</small></span><svg viewBox="0 0 150 42"><polyline points="${spark(indices.indexOf(n),150,42)}" fill="none" stroke="#168567" stroke-width="2"/></svg></div></button>`}).join('')}</div><div class="market-grid"><section class="panel indices-panel"><div class="panel-heading"><h2>热门指数</h2><span class="muted">${list.length} 个指数</span></div><div class="filters">${['全部市场','A 股','港股','美股','红利专题'].map(m=>`<button class="${m===state.market?'on':''}" data-market="${m}">${m}</button>`).join('')}</div><label class="search">⌕ <input id="search" placeholder="搜索名称或代码" value="${esc(state.query)}" aria-label="搜索指数"></label><div class="table-scroll"><table class="index-table"><thead><tr><th>指数名称</th><th>最新点位</th><th>涨跌幅</th><th></th></tr></thead><tbody>${list.map(n=>`<tr data-index="${n.id}" tabindex="0" class="${n.id===i.id?'chosen':''}"><td><strong>${n.name}</strong><small>${n.code} · ${n.market}</small></td><td>${fmt(n.value)}</td><td class="${n.change>=0?'up':'down'}">${n.change>=0?'+':''}${n.change.toFixed(2)}%</td><td><button class="star ${state.watch.includes(n.id)?'starred':''}" data-watch="${n.id}" aria-label="${state.watch.includes(n.id)?'移除':'添加'}${n.name}自选">${state.watch.includes(n.id)?'★':'☆'}</button></td></tr>`).join('')||'<tr><td colspan="4" class="empty">没有匹配的指数</td></tr>'}</tbody></table></div></section><div class="detail-column"><section class="panel detail"><div class="panel-heading"><div><span class="eyebrow">${i.code} / ${i.market}</span><h2>${i.name} <small class="tag">指数</small></h2></div><button class="btn small" data-watch="${i.id}">${state.watch.includes(i.id)?'★ 已自选':'☆ 加入自选'}</button></div><div class="quote"><b>${fmt(i.value)}</b><span class="${i.change>=0?'up':'down'}">${i.change>=0?'+':''}${i.change.toFixed(2)}%</span><small>演示收盘 · 2026-09-10</small></div>${MarketChart.render(i)}<div class="quote-meta"><div>开盘<span>${fmt(MarketChart.dailyData(i).at(-1).open)}</span></div><div>最高<span>${fmt(MarketChart.dailyData(i).at(-1).high)}</span></div><div>最低<span>${fmt(MarketChart.dailyData(i).at(-1).low)}</span></div><div>数据来源<span>合成演示数据</span></div></div></section><section class="signal-panel"><div class="signal-icon">✧</div><div><div class="row"><h2>策略观察</h2><span class="pill ${signalClass(i)}">${i.signal}</span></div><p>${i.signal.includes('入场')?'短期均线向上穿越长期均线，演示入场条件满足。':i.signal.includes('离场')?'短期均线跌破长期均线，演示离场条件满足。':'当前没有新的均线交叉事件，继续观察趋势变化。'}</p><div class="signal-foot"><span>MA20 / MA60 · 风险：${i.risk} · 示例规则 v1</span><button class="text-btn" data-ask="分析${i.name}">让 Agent 解读 ↗</button></div></div></section></div></div>`}
function watchView(){return `${title('WATCHLIST','你的关注，持续追踪','自选保存在当前浏览器。选择指数查看行情与信号。','<button class="btn primary" data-page="market">＋ 添加指数</button>')}<div class="watch-grid">${state.watch.map(id=>{const i=indices.find(x=>x.id===id);return `<section class="panel watch-card"><div class="row"><h2>${i.name}</h2><button class="star starred" data-watch="${id}" aria-label="移除${i.name}自选">★</button></div><small>${i.code} · ${i.market}</small><div class="quote"><b>${fmt(i.value)}</b><span class="${i.change>=0?'up':'down'}">${i.change>0?'+':''}${i.change}%</span></div><svg viewBox="0 0 360 80"><polyline points="${spark(indices.indexOf(i),360,80,i.change>0)}" fill="none" stroke="#168567" stroke-width="2"/></svg><div class="row"><span class="pill ${signalClass(i)}">${i.signal}</span><span class="muted">风险 ${i.risk}</span></div><p>双均线 MA20 / MA60<br>信号截止 2026-09-10 · 合成数据</p><button class="btn full" data-detail="${id}">查看指数详情 ↗</button></section>`}).join('')||'<div class="panel empty">还没有自选指数，去行情总览添加你关注的市场。</div>'}</div>`}
function portfolioView(){let a=state.account,value=a.positions.reduce((s,p)=>s+p.qty*products.find(x=>x.ticker===p.ticker).price,0),cost=a.positions.reduce((s,p)=>s+p.qty*p.cost,0);return `${title('PAPER PORTFOLIO','把每一笔决策记录下来','人民币模拟账户 · 关联 ETF 手工记账','<div class="actions"><button class="btn" data-trade="initial">录入期初持仓</button><button class="btn primary" data-trade="buy">＋ 模拟交易</button></div>')}<div class="metrics"><div class="panel metric"><span>账户总资产 · CNY</span><b>¥ ${fmt(a.cash+value)}</b><small>现金 + 当前持仓市值</small></div><div class="panel metric"><span>可用现金</span><b>¥ ${fmt(a.cash)}</b><small>模拟资金</small></div><div class="panel metric"><span>持仓市值</span><b>¥ ${fmt(value)}</b><small>${a.positions.length} 只 ETF</small></div><div class="panel metric"><span>持仓浮动盈亏</span><b class="${value-cost>=0?'up':'down'}">${value-cost>=0?'+':''}${fmt(value-cost)}</b><small>按演示估值计算</small></div></div><section class="panel"><div class="panel-heading"><h2>当前持仓</h2><span class="tag">模拟 · CNY</span></div><div class="table-scroll"><table><thead><tr><th>产品 / 代码</th><th>持有数量</th><th>平均成本</th><th>演示估值</th><th>浮动盈亏</th><th>操作</th></tr></thead><tbody>${a.positions.map(p=>{let n=products.find(n=>n.ticker===p.ticker),pnl=p.qty*(n.price-p.cost);return `<tr><td><strong>${n.name}</strong><small>${n.ticker} · ETF</small></td><td>${fmt(p.qty,0)}</td><td>${fmt(p.cost,3)}</td><td>${fmt(n.price,3)}</td><td class="${pnl>=0?'up':'down'}">${fmt(pnl)}</td><td><button class="text-btn" data-trade="buy" data-product="${n.ticker}">买入</button><button class="text-btn down" data-trade="sell" data-product="${n.ticker}">卖出</button></td></tr>`}).join('')||'<tr><td colspan="6" class="empty">暂无持仓</td></tr>'}</tbody></table></div></section><section class="panel ledger"><div class="panel-heading"><h2>交易与调整流水</h2><span class="muted">${a.ledger.length} 笔记录</span></div>${a.ledger.length?`<div class="table-scroll"><table><thead><tr><th>日期</th><th>产品</th><th>类型</th><th>数量 / 价格</th><th>费用</th><th>现金变动</th></tr></thead><tbody>${a.ledger.map(l=>`<tr><td>${l.date}</td><td>${l.name}</td><td>${l.type}</td><td>${l.qty} / ${fmt(l.price,3)}</td><td>${fmt(l.fee)}</td><td>${fmt(l.cashChange)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">尚无新交易。买卖或录入持仓后，记录会显示在这里。</div>'}</section>`}
function agentView(){return Research.agentPage()}
function backtestView(){return Research.backtestPage()}
function dialogView(){if(state.dialog==='strategy')return Research.strategyDialog();if(state.dialog==='settings')return `<div class="overlay"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><div class="row"><h2 id="dialog-title">模型与 API 设置</h2><button class="icon-btn" data-close aria-label="关闭">×</button></div><p>配置界面预览。保存后仍为本地演示模式，不会向模型服务发送请求。</p><form id="settings-form"><label>API 服务地址<input name="url" type="url" value="${esc(state.config.url)}" required></label><label>模型名称<input name="model" value="${esc(state.config.model)}" required></label><label>API Key<input name="key" type="password" autocomplete="off" value="${esc(state.config.key)}" placeholder="sk-…"></label><div class="note">Key 仅存于当前页面内存，刷新即清除；不会写入浏览器存储。</div><button class="btn primary full">保存当前会话设置</button></form></section></div>`;return `<div class="overlay"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><div class="row"><h2 id="dialog-title">${state.trade==='initial'?'录入期初持仓':'模拟交易'}</h2><button class="icon-btn" data-close aria-label="关闭">×</button></div><p>手工记录 ETF 数量与成交价，所有金额以 CNY 记账。</p>${state.trade==='initial'?'':`<div class="trade-tabs"><button data-type="buy" class="${state.trade==='buy'?'on':''}">买入</button><button data-type="sell" class="${state.trade==='sell'?'on':''}">卖出</button></div>`}<form id="trade-form"><label>ETF 产品<select name="ticker">${products.map(p=>`<option value="${p.ticker}" ${state.product===p.ticker?'selected':''}>${p.name} · ${p.ticker}</option>`).join('')}</select></label><div class="form-row"><label>数量<input type="number" name="qty" min="1" step="1" value="100" required></label><label>${state.trade==='initial'?'平均成本':'成交价格'}<input type="number" name="price" min="0.001" step="0.001" value="${products.find(p=>p.ticker===(state.product||'510300')).price}" required></label></div><div class="form-row"><label>日期<input name="date" type="date" value="2026-09-11" max="2026-09-11" required></label><label>手续费<input name="fee" type="number" min="0" step="0.01" value="${state.trade==='initial'?0:5}" ${state.trade==='initial'?'readonly':''} required></label></div><div class="note">${state.trade==='initial'?'添加期初数量，并与已有持仓合并计算成本；不扣减现金。':`可用现金 ¥ ${fmt(state.account.cash)} · 成交后同步更新现金与持仓。`}</div><p id="trade-error" class="form-error" role="alert"></p><button class="btn primary full">确认${state.trade==='buy'?'模拟买入':state.trade==='sell'?'模拟卖出':'录入持仓'}</button></form></section></div>`}
function sendChat(text){Research.send(text)}
function bind(){document.querySelectorAll('[data-page]').forEach(el=>el.onclick=e=>{e.preventDefault();state.page=el.dataset.page;render()});document.querySelectorAll('[data-index]').forEach(el=>{el.onclick=()=>{state.selected=el.dataset.index;render()};el.onkeydown=e=>{if(e.key==='Enter'){state.selected=el.dataset.index;render()}}});document.querySelectorAll('[data-watch]').forEach(el=>el.onclick=e=>{e.stopPropagation();let id=el.dataset.watch;state.watch=state.watch.includes(id)?state.watch.filter(x=>x!==id):[...state.watch,id];persist();render();toast('自选列表已更新')});document.querySelectorAll('[data-market]').forEach(el=>el.onclick=()=>{state.market=el.dataset.market;render()});document.querySelectorAll('[data-range]').forEach(el=>el.onclick=()=>{state.range=el.dataset.range;render()});document.querySelectorAll('[data-detail]').forEach(el=>el.onclick=()=>{state.page='market';state.selected=el.dataset.detail;render()});document.querySelectorAll('[data-action="settings"]').forEach(el=>el.onclick=()=>{state.dialog='settings';render();setTimeout(()=>$('#settings-form input')?.focus(),0)});document.querySelectorAll('[data-close]').forEach(el=>el.onclick=()=>{state.dialog=null;render()});document.querySelectorAll('[data-trade]').forEach(el=>el.onclick=()=>{state.dialog='trade';state.trade=el.dataset.trade;state.product=el.dataset.product||'510300';render()});document.querySelectorAll('[data-type]').forEach(el=>el.onclick=()=>{state.trade=el.dataset.type;render()});document.querySelectorAll('[data-chat]').forEach(el=>el.onclick=()=>sendChat(el.dataset.chat));document.querySelectorAll('[data-ask]').forEach(el=>el.onclick=()=>{state.page='agent';sendChat(el.dataset.ask)});
if($('#search'))$('#search').oninput=e=>{let pos=e.target.selectionStart;state.query=e.target.value;render();$('#search').focus();$('#search').setSelectionRange(pos,pos)};
if($('#chat-form'))$('#chat-form').onsubmit=e=>{e.preventDefault();let t=new FormData(e.target).get('message').trim();if(t)sendChat(t)};
if($('#settings-form'))$('#settings-form').onsubmit=e=>{e.preventDefault();state.config=Object.fromEntries(new FormData(e.target));state.dialog=null;render();toast('会话设置已保存 · 仍为演示模式')};
if($('#trade-form')){$('#trade-form select').onchange=e=>{$('#trade-form [name="price"]').value=products.find(p=>p.ticker===e.target.value).price};$('#trade-form').onsubmit=submitTrade}
if($('#backtest-form'))$('#backtest-form').onsubmit=e=>{e.preventDefault();let d=Object.fromEntries(new FormData(e.target));for(let k of ['short','long','capital','fee','slippage'])d[k]=Number(d[k]);if(d.short>=d.long||d.start>=d.end){$('#backtest-error').textContent='短期均线需小于长期均线，开始日期需早于结束日期。';return}let days=(new Date(d.end)-new Date(d.start))/86400000;let seed=indices.findIndex(i=>i.id===d.index)+d.short*.2+d.long*.07+days*.001+d.fee*2+d.slippage*3;state.backtest={...d,seed,return:Math.max(-95,(9+Math.sin(seed)*6)*days/365-d.fee*18-d.slippage*22),drawdown:5+Math.abs(Math.sin(seed+1))*8};render();toast('演示回测已完成')};
document.onkeydown=e=>{if(e.key==='Escape'&&state.dialog){state.dialog=null;render()}if(e.key==='Tab'&&state.dialog){let f=[...document.querySelectorAll('.modal button,.modal input,.modal select')].filter(el=>!el.disabled);if(e.shiftKey&&document.activeElement===f[0]){e.preventDefault();f.at(-1).focus()}else if(!e.shiftKey&&document.activeElement===f.at(-1)){e.preventDefault();f[0].focus()}}};if(state.dialog)requestAnimationFrame(()=>$('.modal button')?.focus());}
function submitTrade(e){e.preventDefault();let d=Object.fromEntries(new FormData(e.target)),qty=Number(d.qty),price=Number(d.price),fee=Number(d.fee),a=state.account,p=a.positions.find(p=>p.ticker===d.ticker),amount=qty*price,fail=t=>$('#trade-error').textContent=t;if(!Number.isFinite(amount)||qty<1||!Number.isInteger(qty)||price<=0||fee<0)return fail('请填写有效的数量、价格和手续费。');if(state.trade==='sell'&&(!p||p.qty<qty))return fail(`卖出数量超过可用持仓（${p?.qty||0} 份）。`);if(state.trade==='buy'&&amount+fee>a.cash)return fail('可用现金不足，请减少买入数量。');if(state.trade==='sell'&&a.cash+amount-fee<0)return fail('可用资金不足以支付本次手续费。');let change=state.trade==='initial'?0:state.trade==='buy'?-(amount+fee):amount-fee;if(state.trade==='sell'){p.qty-=qty;a.positions=a.positions.filter(p=>p.qty>0)}else if(p){p.cost=(p.cost*p.qty+amount+fee)/(p.qty+qty);p.qty+=qty}else a.positions.push({ticker:d.ticker,qty,cost:(amount+fee)/qty});a.cash=Math.round((a.cash+change)*100)/100;a.ledger.unshift({date:d.date,name:products.find(p=>p.ticker===d.ticker).name,type:state.trade==='initial'?'期初录入':state.trade==='buy'?'模拟买入':'模拟卖出',qty,price,fee,cashChange:change});persist();state.dialog=null;render();toast('已记录，持仓与账户数据已更新')}
Research.init(state,{indices,products,fmt,title,chart,render,toast});
render();
